    { const char * tb_v876 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v876; }
    { const char * tb_v877 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v877; }
    { const char * tb_v878 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v878; }
    { const char * tb_v879 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v879; }
    { const char * tb_v880 = "TB_COLD static void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v880; }
    { const char * tb_v881 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v881; }
    { const char * tb_v882 = "    // в терминале — красным (если не задан NO_COLOR)\n"; *(const char * *)tb_grow(v_lines) = tb_v882; }
    { const char * tb_v883 = "    int color = isatty(2) && getenv(\"NO_COLOR\") == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v883; }
    { const char * tb_v884 = "    if (color) fputs(\"\\033[31m\", stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v884; }
    { const char * tb_v885 = "    if (line > 0) fprintf(stderr, \"строка %d: %s\", line, msg);\n"; *(const char * *)tb_grow(v_lines) = tb_v885; }
    { const char * tb_v886 = "    else fprintf(stderr, \"%s\", msg);\n"; *(const char * *)tb_grow(v_lines) = tb_v886; }
    { const char * tb_v887 = "    fputs(color ? \"\\033[0m\\n\" : \"\\n\", stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v887; }
    { const char * tb_v888 = "    exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v888; }
    { const char * tb_v889 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v889; }
    { const char * tb_v890 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v890; }
    { const char * tb_v891 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v891; }
    { const char * tb_v892 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v892; }
    { const char * tb_v893 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v893; }
    { const char * tb_v894 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v894; }
    { const char * tb_v895 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v895; }
    { const char * tb_v896 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v896; }
    { const char * tb_v897 = "static _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v897; }
