    { const char * tb_v899 = "#define TB_THREAD_STACK (8LL << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v899; }
    { const char * tb_v900 = "static void tb_on_segv(int sig, siginfo_t *si, void *u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v900; }
    { const char * tb_v901 = "    (void)sig; (void)u;\n"; *(const char * *)tb_grow(v_lines) = tb_v901; }
    { const char * tb_v902 = "    char *a = (char *)si->si_addr;\n"; *(const char * *)tb_grow(v_lines) = tb_v902; }
