    { const char * tb_v905 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v905; }
    { const char * tb_v906 = "        struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v906; }
    { const char * tb_v907 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v907; }
    { const char * tb_v908 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v908; }
    { const char * tb_v909 = "    const char *m;\n"; *(const char * *)tb_grow(v_lines) = tb_v909; }
    { const char * tb_v910 = "    if (tb_main_sp && a <= tb_main_sp + 65536 && a >= tb_main_sp - lim - (1 << 20))\n"; *(const char * *)tb_grow(v_lines) = tb_v910; }
    { const char * tb_v911 = "        m = \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v911; }
    { const char * tb_v912 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v912; }
    { const char * tb_v913 = "        m = \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v913; }
    { const char * tb_v914 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v914; }
    { const char * tb_v915 = "    _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v915; }
    { const char * tb_v916 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v916; }
    { const char * tb_v917 = "// свой маленький стек для сообщения: у главного потока — постоянный, у остальных — из malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v917; }
    { const char * tb_v918 = "static void tb_guard_thread(char *here, long long lim) {\n"; *(const char * *)tb_grow(v_lines) = tb_v918; }
    { const char * tb_v919 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v919; }
