    { const char * tb_v925 = "// поток background или ядра: сначала ставим защиту стека, потом сама работа\n"; *(const char * *)tb_grow(v_lines) = tb_v925; }
    { const char * tb_v926 = "// сколько потоков background / ядер работает сейчас: уборка памяти ждёт, пока их нет\n"; *(const char * *)tb_grow(v_lines) = tb_v926; }
    { const char * tb_v927 = "static int tb_gthreads = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v927; }
    { const char * tb_v928 = "typedef struct { void *(*run)(void *); void *arg; } tb_tramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v928; }
