    { const char * tb_v941 = "// поток с 8 МБ стека (на Mac по умолчанию всего 512 КБ) и с понятным сообщением при переполнении\n"; *(const char * *)tb_grow(v_lines) = tb_v941; }
    { const char * tb_v942 = "static int tb_thread_create(pthread_t *th, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v942; }
    { const char * tb_v943 = "    tb_tramp *t = malloc(sizeof(tb_tramp));\n"; *(const char * *)tb_grow(v_lines) = tb_v943; }
    { const char * tb_v944 = "    if (!t) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v944; }
    { const char * tb_v945 = "    t->run = run; t->arg = arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v945; }
    { const char * tb_v946 = "    pthread_attr_t at;\n"; *(const char * *)tb_grow(v_lines) = tb_v946; }
    { const char * tb_v947 = "    pthread_attr_init(&at);\n"; *(const char * *)tb_grow(v_lines) = tb_v947; }
