    { const char * tb_v949 = "    __atomic_add_fetch(&tb_gthreads, 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v949; }
    { const char * tb_v950 = "    int r = pthread_create(th, &at, tb_tramp_run, t);\n"; *(const char * *)tb_grow(v_lines) = tb_v950; }
    { const char * tb_v951 = "    pthread_attr_destroy(&at);\n"; *(const char * *)tb_grow(v_lines) = tb_v951; }
    { const char * tb_v952 = "    if (r != 0) { free(t); __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v952; }
    { const char * tb_v953 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v953; }
