    { const char * tb_v955 = "static void tb_guard_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v955; }
    { const char * tb_v956 = "    static char alt[65536];\n"; *(const char * *)tb_grow(v_lines) = tb_v956; }
