    { const char * tb_v969 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v969; }
    { const char * tb_v970 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v970; }
    { const char * tb_v971 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v971; }
    { const char * tb_v972 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v972; }
    { const char * tb_v973 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v973; }
    { const char * tb_v974 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v974; }
    { const char * tb_v975 = "static _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v975; }
    { const char * tb_v976 = "static _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v976; }
    { const char * tb_v977 = "static int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v977; }
    { const char * tb_v978 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v978; }
    { const char * tb_v979 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v979; }
    { const char * tb_v980 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v980; }
