    { const char * tb_v982 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v982; }
    { const char * tb_v983 = "static void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v983; }
    { const char * tb_v984 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v984; }
    { const char * tb_v985 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
