    { const char * tb_v1045 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1045; }
    { const char * tb_v1046 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v1046; }
    { const char * tb_v1047 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1047; }
    { const char * tb_v1048 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v1048; }
    { const char * tb_v1049 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v1049; }
    { const char * tb_v1050 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v1050; }
    { const char * tb_v1051 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v1051; }
    { const char * tb_v1052 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v1052; }
    { const char * tb_v1053 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v1053; }
    { const char * tb_v1054 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v1054; }
    { const char * tb_v1055 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1055; }
    { const char * tb_v1056 = "static void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1056; }
    { const char * tb_v1057 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1057; }
    { const char * tb_v1058 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1058; }
