    { const char * tb_v1077 = "static const long long tb_gsz[TB_GNC] = {16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128, 160, 192, 224, 256,\n"; *(const char * *)tb_grow(v_lines) = tb_v1077; }
