    { const char * tb_v1146 = "    char *m = mmap(0, tot, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1146; }
