    { const char * tb_v2420 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2420; }
    { const char * tb_v2421 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2421; }
    { const char * tb_v2422 = "static void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2422; }
    { const char * tb_v2423 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2423; }
    { const char * tb_v2424 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v2424; }
