    { const char * tb_v2439 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2439; }
    { const char * tb_v2440 = "static tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2440; }
    { const char * tb_v2441 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2441; }
