    { const char * tb_v2446 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2446; }
    { const char * tb_v2447 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2447; }
    { const char * tb_v2448 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2448; }
    { const char * tb_v2449 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2449; }
    { const char * tb_v2450 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v2450; }
    { const char * tb_v2451 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v2451; }
    { const char * tb_v2452 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v2452; }
    { const char * tb_v2453 = "static pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2453; }
    { const char * tb_v2454 = "static int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2454; }
    { const char * tb_v2455 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v2455; }
    { const char * tb_v2456 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v2456; }
    { const char * tb_v2457 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2457; }
    { const char * tb_v2458 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2458; }
    { const char * tb_v2459 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2459; }
    { const char * tb_v2460 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2460; }
    { const char * tb_v2461 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2461; }
    { const char * tb_v2462 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2462; }
    { const char * tb_v2463 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2463; }
    { const char * tb_v2464 = "    for (int i = 1; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2464; }
    { const char * tb_v2465 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2465; }
    { const char * tb_v2466 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2466; }
    { const char * tb_v2467 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2467; }
    { const char * tb_v2468 = "        if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2468; }
    { const char * tb_v2469 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2469; }
    { const char * tb_v2470 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2470; }
    { const char * tb_v2471 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2471; }
    { const char * tb_v2472 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2472; }
    { const char * tb_v2473 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2473; }
    { const char * tb_v2474 = "static long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2474; }
    { const char * tb_v2475 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v2475; }
    { const char * tb_v2476 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v2476; }
    { const char * tb_v2477 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2477; }
    { const char * tb_v2478 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2478; }
    { const char * tb_v2479 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2479; }
